// System back goes to the previous step before it leaves the flow.
BackHandler(enabled = step > 0 && !done) { step-- }
if (done) {
    MonarchEmptyState(
        title = "Booking complete",
        kind = MonarchEmptyStateKind.Success,
        message = "We sent the details by email.",
    )
} else {
    Column(Modifier.padding(vertical = MonarchTheme.spacing.space4), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
        MonarchStepper(
            steps = steps.mapIndexed { i, s -> MonarchStepperStep(s.id, s.label, complete = i < step) },
            current = step,
            compact = MonarchStepperCompactMode.Never,
            onSelect = { _, index -> if (index < step) step = index },
        )
        Column(
            modifier = Modifier.fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        ) {
            MonarchText(
                text = "STEP " + (step + 1) + " OF " + steps.size,
                style = MonarchTextStyle.Caption,
                color = MonarchTheme.colors.textMuted,
            )
            MonarchText(
                text = titles[step],
                modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite },
                style = MonarchTextStyle.Heading,
                heading = true,
            )
            when (step) {
                0 -> services.forEach { option ->
                    MonarchButton(
                        text = option,
                        onClick = {
                            service = option
                            step++
                        },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Secondary,
                    )
                }
                1 -> MonarchSlotPicker(
                    slots = listOf(0L, 1_800_000L).map { MonarchSlotPickerSlot((day ?: nov4) + 32_400_000L + it) },
                    selection = slot,
                    onSelectionChange = { slot = it },
                    day = day,
                    onDayChange = {
                        day = it
                        slot = null
                    },
                    timeZone = zone,
                    previousMonthIcon = {
                        MonarchIcon(SampleIcons.ChevronLeft, null)
                    },
                    nextMonthIcon = {
                        MonarchIcon(SampleIcons.ChevronRight, null)
                    },
                    today = nov4,
                    onTimeZoneChange = { zone = it },
                )
                2 -> MonarchTextField(value = name, onValueChange = { name = it }, label = "Name")
                else -> MonarchDescriptionList(
                    items = listOf(
                        MonarchDescriptionItem("Service", service),
                        MonarchDescriptionItem("Time zone", zone),
                        MonarchDescriptionItem("Name", name),
                    ),
                )
            }
        }
        if (step > 0) Row(verticalAlignment = Alignment.CenterVertically) {
            if (step > 0) MonarchButton(text = "Back", onClick = { step-- }, variant = MonarchButtonVariant.Ghost)
            Spacer(Modifier.weight(1f))
            MonarchButton(
                text = if (step == steps.lastIndex) "Confirm booking" else "Continue",
                onClick = { if (step == steps.lastIndex) done = true else step++ },
                variant = MonarchButtonVariant.Primary,
                enabled = complete,
            )
        }
    }
}

examples.setupTemplate:
val nov4 = 1_793_750_400_000L
val steps = listOf(
    MonarchStepperStep({{steps.0.id}}, {{steps.0.label}}),
    MonarchStepperStep({{steps.1.id}}, {{steps.1.label}}),
    MonarchStepperStep({{steps.2.id}}, {{steps.2.label}}),
    MonarchStepperStep({{steps.3.id}}, {{steps.3.label}}),
)
val services = listOf(
    {{services.0.name}} + " · {{services.0.minutes|raw}} min",
    {{services.1.name}} + " · {{services.1.minutes|raw}} min",
)
val titles = listOf({{steps.0.title}}, "Choose a date and time", "Enter your details", "Check and confirm")
var step by rememberSaveable { mutableIntStateOf(0) }
var service by rememberSaveable { mutableStateOf<String?>(null) }
var day by rememberSaveable { mutableStateOf<Long?>(nov4) }
var slot by rememberSaveable { mutableStateOf<Long?>(null) }
var zone by rememberSaveable { mutableStateOf("Europe/London") }
var name by rememberSaveable { mutableStateOf("") }
var done by rememberSaveable { mutableStateOf(false) }
val complete = when (step) {
    0 -> service != null
    1 -> slot != null
    2 -> name.isNotBlank()
    else -> true
}

